-- Additive IAM grants: fcf4c4c -> dd3b946 (generated by scripts/gen-permission-grants.ts --since fcf4c4c).
-- Idempotent (every insert is NOT EXISTS-guarded); one transaction. Apply with psql -v ON_ERROR_STOP=1
-- against the RawProd MAIN database as the owner (DDL/DML) role. Never instead of this: pnpm db:seed.
-- New permission codes (6): production:cover_plan:read, production:cover_plan:write, production:qc_review:approve, production:qc_review:perfumer, production:qc_review:read, production:qc_review_setup:write
-- New roles (0): none
-- New grants (22):
--   owner                  production:cover_plan:read
--   owner                  production:cover_plan:write
--   owner                  production:qc_review:approve
--   owner                  production:qc_review:perfumer
--   owner                  production:qc_review:read
--   owner                  production:qc_review_setup:write
--   admin                  production:cover_plan:read
--   admin                  production:cover_plan:write
--   admin                  production:qc_review:read
--   admin                  production:qc_review_setup:write
--   procurement            production:cover_plan:read
--   qc                     production:qc_review:read
--   production             production:cover_plan:read
--   production             production:cover_plan:write
--   production             production:qc_review:read
--   formulator             production:qc_review:perfumer
--   formulator             production:qc_review:read
--   vault_approver         production:qc_review:approve
--   vault_approver         production:qc_review:read
--   vault_approver         production:qc_review_setup:write
--   showcase               production:cover_plan:read
--   showcase               production:qc_review:read

begin;

insert into iam.permission_master (permission_code, permission_name, module_name, status, created_by, updated_by)
select v.code, v.code, split_part(v.code, ':', 1), 'ACTIVE', 'release-grant', 'release-grant'
  from (values ('production:cover_plan:read'), ('production:cover_plan:write'), ('production:qc_review:approve'), ('production:qc_review:perfumer'), ('production:qc_review:read'), ('production:qc_review_setup:write')) as v(code)
 where not exists (select 1 from iam.permission_master p where p.permission_code = v.code);

insert into iam.role_permission_mapping (role_id, permission_id, status, created_by, updated_by)
select r.role_id, p.permission_id, 'ACTIVE', 'release-grant', 'release-grant'
  from (values
    ('owner', 'production:cover_plan:read'),
    ('owner', 'production:cover_plan:write'),
    ('owner', 'production:qc_review:approve'),
    ('owner', 'production:qc_review:perfumer'),
    ('owner', 'production:qc_review:read'),
    ('owner', 'production:qc_review_setup:write'),
    ('admin', 'production:cover_plan:read'),
    ('admin', 'production:cover_plan:write'),
    ('admin', 'production:qc_review:read'),
    ('admin', 'production:qc_review_setup:write'),
    ('procurement', 'production:cover_plan:read'),
    ('qc', 'production:qc_review:read'),
    ('production', 'production:cover_plan:read'),
    ('production', 'production:cover_plan:write'),
    ('production', 'production:qc_review:read'),
    ('formulator', 'production:qc_review:perfumer'),
    ('formulator', 'production:qc_review:read'),
    ('vault_approver', 'production:qc_review:approve'),
    ('vault_approver', 'production:qc_review:read'),
    ('vault_approver', 'production:qc_review_setup:write'),
    ('showcase', 'production:cover_plan:read'),
    ('showcase', 'production:qc_review:read')
  ) as g(role_code, permission_code)
  join iam.role_master r on r.role_code = g.role_code
  join iam.permission_master p on p.permission_code = g.permission_code
 where not exists (select 1 from iam.role_permission_mapping m where m.role_id = r.role_id and m.permission_id = p.permission_id);

commit;
